<div class="form-group"><label for="price_type">Loại giá</label><select name="price_type" id="price_type"><option value="purchase">Giá nhập</option><option value="sale" <?= ($old['price_type'] ?? '')==='sale' ? 'selected' : '' ?>>Giá xuất</option></select></div>
